# -*- coding: utf-8 -*-
"""Clarify unlisted-school-system routes and Western's published draft fees."""
import ca50_gaps as G
from ca50_gaps import L
D='2026-10-26';h,rs,t=G.load();u={r['id']:r for r in rs}
src='https://www.sfu.ca/students/admission/admission-requirements/international-highschool/country/basic-requirements.html';r=u['simon-fraser-university']
r['academics'].update(G.plain({'internationalQualifications':L('Uzbekistan is absent from SFU’s country selector; unlisted countries are directed to Basic requirements. The fallback requires university-preparatory school graduation and transcripts. General Math C-/60% is not an Uzbek grade conversion. Business needs senior Math; Engineering also needs Chemistry and Physics. The exact accepted Uzbek credential and required preparation remain unconfirmed. FIC is a separate pathway, not mandatory for every Uzbek applicant.','Узбекистан отсутствует в селекторе SFU; для стран вне списка указаны Basic requirements. Общие условия требуют окончания university-preparatory школы и выписок. Общий порог Math C-/60% не является пересчётом узбекских оценок. Business требует senior Math; Engineering — также Chemistry и Physics. Точный принимаемый узбекский документ и необходимая подготовка не установлены. FIC — отдельный pathway, а не обязательное обучение для всех узбекских абитуриентов.'),'internationalQualificationsSource':src,'internationalQualificationsVerified':D}))
G.source(r,G.plain(L('SFU — official fallback for countries absent from the selector','SFU — официальные общие условия для стран вне селектора')),src)
G.source(r,G.plain(L('SFU — country selector checked; Uzbekistan absent','SFU — селектор стран проверен; Узбекистан отсутствует')),'https://www.sfu.ca/students/admission/admission-requirements/international-highschool/country.html')
r=u['queens-university'];r['academics'].update(G.plain({'internationalQualifications':L('Uzbekistan is absent from the current international country/region selector. The accepted Uzbek qualification, grades, programme subjects and preparatory-study requirements remain unconfirmed. Do not substitute Kazakhstan or another listed country for Uzbekistan.','Узбекистан отсутствует в текущем международном селекторе стран/регионов. Принимаемая узбекская квалификация, оценки, предметы программы и необходимая подготовка не установлены. Нельзя подставлять Казахстан или другую страну из списка вместо Узбекистана.'),'internationalQualificationsVerified':D}))
r=u['university-of-windsor'];f=r['admissions']['applicationFee'];assert f['amount'] is None
src='https://www.uwindsor.ca/registrar/2879/registrarial-service-fees'
f.update(G.plain({'source':src,'verified':D,'note':L('The current Registrarial Service Fees page still links a fee outline for 2022/23–2023/24, revised June 2023. Its C$75 International Contract Application charge does not confirm the current direct international undergraduate fee. OUAC routes, part-time fees, graduate fees and the enrolment deposit are different charges; the current amount remains unknown.','Текущая страница Registrarial Service Fees по-прежнему ведёт на таблицу 2022/23–2023/24 с обновлением июня 2023. Старые C$75 за International Contract Application не подтверждают текущий сбор прямой международной заявки на бакалавриат. Маршруты OUAC, part-time, graduate и депозит — другие платежи; текущая сумма остаётся неизвестной.')}))
G.source(r,G.plain(L('Windsor — current service-fee index links an older schedule','Windsor — текущий указатель сборов ссылается на старую таблицу')),src)
r=u['western-university'];c=r['costs'];oldsrc=c['source'];oldverified=c['verified'];housing=c['items'][1]
housing.update({'source':oldsrc,'verified':oldverified,'academicYear':'2024–2025'})
src='https://registrar.uwo.ca/student_finances/fees_refunds/2026-27-UGRD-Fee-Schedule---FT-International1.pdf'
conflict=L('Western’s 2026–27 international fee schedule is labelled DRAFT. Its UHIP column lists C$948 while the explanatory paragraph states C$792 for September 2026–August 2027. A final consistent billed total is not selected.','Международная таблица Western 2026–27 помечена DRAFT. В столбце UHIP стоят C$948, а поясняющий абзац указывает C$792 за сентябрь 2026 — август 2027. Окончательный согласованный billed total не выбран.')
c.update(G.plain({'status':'conflict','academicYear':'2026–2027','source':src,'verified':D,'studentCategory':L('International first-entry undergraduates, September 2026–April 2027; published draft schedule','Иностранные first-entry бакалавры, сентябрь 2026 — апрель 2027; опубликованная предварительная таблица'),'headline':L('Draft 2026–27 tuition rates; UHIP charge needs clarification','Предварительные tuition-тарифы 2026–27; сбор UHIP требует уточнения'),'breakdown':{'period':'year','includes':L('Draft tuition only; ancillary fees, insurance and living expenses are separate','Предварительное tuition без ancillary fees, страховки и расходов на жизнь')},'items':[
 {'label':L('Draft first-entry Arts/Humanities or general Science/Social Science tuition','Предварительное tuition first-entry Arts/Humanities или общего Science/Social Science'),'amount':47493,'source':src,'verified':D},
 {'label':L('Draft Computer Science tuition, years 1–3','Предварительное tuition Computer Science, годы 1–3'),'amount':55167,'source':src,'verified':D},
 {'label':L('Draft MOS tuition, year 1','Предварительное tuition MOS, год 1'),'amount':60105,'source':src,'verified':D},
 {'label':L('Draft Engineering tuition, year 1','Предварительное tuition Engineering, год 1'),'amount':64310,'source':src,'verified':D},
 housing],
 'billedSubtotal':None,'totalText':L('A 2026–27 international draft now exists. Its first-entry tuition examples are listed above, but no consistent final annual billed total or complete living budget is confirmed. The older residence estimate keeps its 2024–25 label and earlier source/date.','Найдена международная предварительная таблица 2026–27. Примеры first-entry tuition приведены выше, но согласованный окончательный годовой billed total и полный бюджет жизни не подтверждены. Старый ориентир жилья сохраняет подпись 2024–25 и прежние источник/дату.'),'note':L('The schedule says DRAFT: FEES MAY CHANGE WITHOUT NOTICE. The table and paragraph disagree on UHIP; do not select one silently. A first-time Western One Card costs C$50 outside the table. First-entry tuition after year 1 has a maximum 4% annual increase under the Registrar’s stated conditions; second-entry programmes are outside that guarantee. No draft figure is used to promise budget sufficiency.','В таблице указано DRAFT: FEES MAY CHANGE WITHOUT NOTICE. Столбец и абзац расходятся по UHIP; нельзя молча выбирать одну сумму. Для впервые поступающих Western One Card стоит C$50 сверх таблицы. Рост first-entry tuition после первого года ограничен 4% в год при условиях Registrar; second-entry программы в гарантию не входят. Предварительные суммы не используются для обещания достаточного бюджета.'),'conflict':{'text':conflict,'sources':[{'label':L('Western — published draft international schedule, 2026–27','Western — опубликованная предварительная международная таблица 2026–27'),'url':src}]}}))
G.source(r,G.plain(L('Western — current draft international tuition and ancillary schedule, 2026–27','Western — текущая предварительная таблица international tuition и ancillary, 2026–27')),src)
G.source(r,G.plain(L('Western — fee index and tuition guarantee','Western — указатель сборов и гарантия tuition')),'https://registrar.uwo.ca/student_finances/fees_refunds/fee_refund_schedules.html')
G.save(h,rs,t);G.flush()
